package ktanesolver.module.modded.regular.colorfulmadness;import static org.assertj.core.api.Assertions.assertThat;import java.util.*;import org.junit.jupiter.api.Test;import ktanesolver.entity.*;import ktanesolver.enums.PortType;import ktanesolver.logic.*;import ktanesolver.module.modded.regular.colorfulmadness.ColorfulMadnessInput.*;
class ColorfulMadnessSolverTest{private final ColorfulMadnessSolver s=new ColorfulMadnessSolver();@Test void appliesAllThreeModifiersAndFindsCounterparts(){BombEntity b=new BombEntity();b.setSerialNumber("A1A2A3");b.setAaBatteryCount(2);b.setDBatteryCount(1);b.replacePortPlates(List.of(Set.of(PortType.DVI,PortType.RJ45),Set.of(PortType.SERIAL)));List<Button>buttons=buttons();buttons.set(0,new Button(true,Pattern.CHECKERBOARD_4,20));buttons.set(9,new Button(false,Pattern.OTHER,11));buttons.set(1,new Button(false,Pattern.SQUARE_ON_SQUARE,19));buttons.set(8,new Button(false,Pattern.OTHER,12));var out=solve(b,buttons);assertThat(out.mainPositions()).containsExactly(10,8,9);assertThat(out.presses()).containsExactly(10,8,9,11,18,12);}@Test void makesDuplicateDigitsUniqueInSpecifiedDirections(){BombEntity b=new BombEntity();b.setSerialNumber("A0A0A0");var out=solve(b,buttons());assertThat(out.mainPositions()).containsExactly(2,10,1);}@Test void validatesCounterpartPermutation(){BombEntity b=new BombEntity();b.setSerialNumber("ABC123");List<Button>x=buttons();x.set(1,new Button(false,Pattern.OTHER,11));assertThat(s.solve(new RoundEntity(),b,new ModuleEntity(),new ColorfulMadnessInput(x))).isInstanceOf(SolveFailure.class);}private ColorfulMadnessOutput solve(BombEntity b,List<Button>x){return((SolveSuccess<ColorfulMadnessOutput>)s.solve(new RoundEntity(),b,new ModuleEntity(),new ColorfulMadnessInput(x))).output();}private static List<Button>buttons(){List<Button>x=new ArrayList<>();for(int i=0;i<10;i++)x.add(new Button(false,Pattern.OTHER,11+i));return x;}}
